import sys
import requests
from requests.exceptions import RequestException
from datetime import datetime

def process_urls(input_file):
    urls = []
    with open(input_file, 'r') as f:
        for line in f:
            stripped_line = line.strip()
            if stripped_line:
                urls.append(stripped_line)

    results = []
    for url in urls:
        try:
            response = requests.get(url, timeout=10)
            status_code = response.status_code
            results.append((url, str(status_code)))
        except RequestException:
            results.append((url, "Error"))

    return results

def generate_html_report(results):
    html_content = """<!DOCTYPE html>
<html>
<head>
    <title>URL Status Report</title>
    <style>
        table {
            border-collapse: collapse;
            width: 100%;
        }
        th, td {
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }
        th {
            background-color: #f2f2f2;
        }
    </style>
</head>
<body>
    <h1>URL Status Report</h1>
    <table>
        <tr>
            <th>URL</th>
            <th>Status Code</th>
        </tr>
"""
    for url, status in results:
        html_content += f"""        <tr>
            <td>{url}</td>
            <td>{status}</td>
        </tr>
"""
    html_content += """
    </table>
</body>
</html>
"""
    with open('report.html', 'w') as f:
        f.write(html_content)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python url_report.py <input_file>")
        sys.exit(1)

    input_file = sys.argv[1]
    results = process_urls(input_file)
    generate_html_report(results)

